    """Return the run-length encoding of s, for example "aaabcc" -> "a3b1c2"."""
    compressed = ""
    i = 0
    while i < len(s):
        count = 0
        while i < len(s) and s[i] == s[i - 1]:
            count += 1
            i += 1
        if count > 1:
            compressed += f"{count}{s[i - 1]}"
        else:
            compressed += s[i - 1]
        i += 1
    return compressed

