def flatten(nested: list) -> list:
    """Return all integers in nested (a list of ints and lists, at any depth) in one list."""
    # Base case: if the list is empty or contains only integers, return it as a list
    if not nested or isinstance(nested, int):
        return [nested]

    # Recursive case: flatten the nested list and append the integer to the result
    result = flatten(nested[0])
    for item in nested[1:]:
        result.extend(flatten(item))

    return result

